            "type": "command",
            "content": "aws wafv2 get-ip-set --scope CLOUDFRONT --region us-east-1 --name example-bot-dev-allowed-ips --id 2efb85f7-5f0d-4473-b8df-eef754982a71 --query '{Addresses:IPSet.Addresses,LockToken:LockToken}'"
